import React from "react";
import {
  FaTrophy,
  FaProjectDiagram,
  FaCalendarAlt,
  FaPalette,
  FaBolt,
  FaUserGraduate,
  FaLeaf,
  FaBrain
} from "react-icons/fa";

const Projects = () => {
  return (
    <section className="projects-page">

      {/* BACKGROUND FX */}
      <div className="bg-glow"></div>
      <div className="particles">
        <span></span><span></span><span></span><span></span><span></span>
      </div>

      {/* HEADER */}
      <div className="section-header">
        <h2>Crafted Works</h2>
        <p>Showcasing ideas transformed into structured, scalable and interactive systems.</p>
      </div>

      {/* PROJECTS */}
      <div className="section projects-section">

        <div className="projects-grid">

          <div className="project-card">
            <div className="badge">01</div>
            <div className="project-icon"><FaBolt /></div>
            <h3>EnergyPulse</h3>
            <p>
              Developed the frontend of an AI-driven smart home solution, creating a responsive dashboard that displays real-time biometric and energy data.
              The interface enables users to monitor and control devices easily.
            </p>
            <div className="tech-tags"><span>React.js</span></div>
          </div>

          <div className="project-card">
            <div className="badge">02</div>
            <div className="project-icon"><FaUserGraduate /></div>
            <h3>Student Portal Management</h3>
            <p>
              Developed a full-stack Student Portal Management System using Java and Spring Boot with structured backend and clean UI.
            </p>
            <div className="tech-tags">
              <span>Spring Boot</span><span>HTML</span><span>CSS</span><span>JS</span><span>MySQL</span>
            </div>
          </div>

          <div className="project-card">
            <div className="badge">03</div>
            <div className="project-icon"><FaLeaf /></div>
            <h3>Farm2Fork</h3>
            <p>
              Built a responsive frontend interface enabling seamless interaction between farmers and consumers.
            </p>
            <div className="tech-tags">
              <span>HTML</span><span>CSS</span><span>JavaScript</span>
            </div>
          </div>

          <div className="project-card">
            <div className="badge">04</div>
            <div className="project-icon cogni">
              <FaBrain />
            </div>
            <h3>Cogni Flow</h3>
            <p>
              Designed an interactive learning-based frontend system focused on structured cognitive flow and smooth UI transitions.
            </p>
            <div className="tech-tags">
              <span>HTML</span><span>CSS</span><span>JavaScript</span>
            </div>
          </div>

        </div>
      </div>

      {/* ACHIEVEMENTS */}
      <div className="section achievements-section">
        <h2>Achievements</h2>

        <div className="achievements-grid">

          <div className="achievement-card">
            <FaTrophy className="achievement-icon" />
            <div>
              <h3>Hackathon Participated</h3>
              <p>Semifinalist in Smart India Hackathon (SIH) 2025.</p>
            </div>
          </div>

          <div className="achievement-card">
            <FaProjectDiagram className="achievement-icon" />
            <div>
              <h3>Project Competitions</h3>
